export class GraphError extends Error {
  constructor(message) {
    super(message)
    this.name = 'GraphError'
  }
}

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^\d+$/

/**
 * Parse the textual build graph into a tasks map (name -> cost) and a deps
 * map (name -> Set of dependency names).
 */
export function parseGraph(input) {
  let raw = input.split('\n')
  if (raw.length > 0 && raw[raw.length - 1] === '') {
    raw.pop()
  }

  const tasks = new Map()
  const depEntries = []

  for (let i = 0; i < raw.length; i++) {
    const lineNo = i + 1
    const trimmed = raw[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new GraphError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const name = words[1]
      const costStr = words[2]
      if (!NAME_RE.test(name)) {
        throw new GraphError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (tasks.has(name)) {
        throw new GraphError(`line ${lineNo}: task ${name} is declared twice`)
      }
      if (!COST_RE.test(costStr)) {
        throw new GraphError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new GraphError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const target = words[1]
      const deps = words.slice(2)
      depEntries.push({ target, deps })
    } else {
      throw new GraphError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const entry of depEntries) {
    if (!tasks.has(entry.target)) {
      throw new GraphError(`unknown task ${entry.target}`)
    }
    for (const dep of entry.deps) {
      if (!tasks.has(dep)) {
        throw new GraphError(`unknown task ${dep}`)
      }
    }
  }

  const deps = new Map()
  for (const entry of depEntries) {
    let set = deps.get(entry.target)
    if (!set) {
      set = new Set()
      deps.set(entry.target, set)
    }
    for (const dep of entry.deps) {
      set.add(dep)
    }
  }

  return { tasks, deps }
}
"}

