{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-lCfMY6/src/graph.js","content":"/**
 * Graph algorithms shared by the waves, explain and pack commands.
 */

export class CycleError extends Error {
  constructor(cycle) {
    super(`cycle: ${cycle.join(' -> ')}`)
    this.name = 'CycleError'
    this.cycle = cycle
  }
}

function depsOf(deps, name) {
  return deps.get(name) || new Set()
}

/**
 * Find the first cycle a depth-first search finds when it starts from each
 * task in ascending name order and walks each task's dependencies in
 * ascending name order. Returns the array of names from the re-entered task
 * through the stack back to that task, or null when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const visited = new Set()
  const onStack = new Set()
  const stack = []

  function dfs(name) {
    stack.push(name)
    onStack.add(name)
    const children = [...depsOf(deps, name)].sort()
    for (const child of children) {
      if (onStack.has(child)) {
        const idx = stack.indexOf(child)
        return stack.slice(idx).concat(child)
      }
      if (!visited.has(child)) {
        const found = dfs(child)
        if (found) return found
      }
    }
    stack.pop()
    onStack.delete(name)
    visited.add(name)
    return null
  }

  for (const name of names) {
    if (!visited.has(name)) {
      const found = dfs(name)
      if (found) return found
    }
  }
  return null
}

/**
 * Compute start, finish and depth for every task, assuming an acyclic
 * graph. Returns a Map name -> { start, finish, depth }.
 */
export function computeSchedule(tasks, deps) {
  const memo = new Map()

  function calc(name) {
    if (memo.has(name)) return memo.get(name)
    const children = [...depsOf(deps, name)]
    let depth = 0
    let start = 0
    if (children.length > 0) {
      let maxDepth = -1
      let maxFinish = 0
      for (const child of children) {
        const c = calc(child)
        if (c.depth > maxDepth) maxDepth = c.depth
        if (c.finish > maxFinish) maxFinish = c.finish
      }
      depth = maxDepth + 1
      start = maxFinish
    }
    const cost = tasks.get(name)
    const finish = start + cost
    const result = { start, finish, depth }
    memo.set(name, result)
    return result
  }

  for (const name of tasks.keys()) {
    calc(name)
  }

  return memo
}

/**
 * Compute the reverse-dependency (dependents) map: name -> Set of names
 * that directly depend on it.
 */
export function computeDependents(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, new Set())
  for (const [name, set] of deps.entries()) {
    for (const dep of set) {
      dependents.get(dep).add(name)
    }
  }
  return dependents
}

/**
 * Compute each task's priority: the cost of the longest chain that begins
 * at it and runs forward through its dependents to a task nothing depends
 * on.
 */
export function computePriority(tasks, dependents) {
  const memo = new Map()

  function calc(name) {
    if (memo.has(name)) return memo.get(name)
    const children = dependents.get(name) || new Set()
    let best = 0
    for (const child of children) {
      const c = calc(child)
      if (c > best) best = c
    }
    const result = tasks.get(name) + best
    memo.set(name, result)
    return result
  }

  for (const name of tasks.keys()) {
    calc(name)
  }

  return memo
}

/**
 * Simulate the graph on the given number of workers using the greatest
 * priority task, breaking ties by ascending name, on the free worker with
 * the smallest index.
 */
export function packSchedule(tasks, deps, workers) {
  const dependents = computeDependents(tasks, deps)
  const priority = computePriority(tasks, dependents)

  const depsRemaining = new Map()
  for (const name of tasks.keys()) {
    depsRemaining.set(name, depsOf(deps, name).size)
  }

  const pending = new Set(tasks.keys())
  const freeAt = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])

  let currentTime = 0

  while (pending.size > 0) {
    let assigned = true
    while (assigned) {
      assigned = false

      let ready = []
      for (const name of pending) {
        if (depsRemaining.get(name) === 0) ready.push(name)
      }
      if (ready.length === 0) break

      let freeIdx = -1
      for (let w = 0; w < workers; w++) {
        if (freeAt[w] <= currentTime) {
          freeIdx = w
          break
        }
      }
      if (freeIdx === -1) break

      ready.sort((a, b) => {
        const pa = priority.get(a)
        const pb = priority.get(b)
        if (pa !== pb) return pb - pa
        return a < b ? -1 : a > b ? 1 : 0
      })
      const name = ready[0]

      const start = currentTime
      const finish = start + tasks.get(name)
      runs[freeIdx].push({ name, start, finish })
      freeAt[freeIdx] = finish
      pending.delete(name)

      for (const dependent of dependents.get(name) || []) {
        depsRemaining.set(dependent, depsRemaining.get(dependent) - 1)
      }

      assigned = true
    }

    if (pending.size === 0) break

    let next = Infinity
    for (let w = 0; w < workers; w++) {
      if (freeAt[w] > currentTime) next = Math.min(next, freeAt[w])
    }
    if (next === Infinity) break
    currentTime = next
  }

  let makespan = 0
  for (const run of runs) {
    for (const task of run) {
      if (task.finish > makespan) makespan = task.finish
    }
  }

  return { runs, makespan }
}
"}

