import { parseGraph, GraphError } from './parse.js'
import { findCycle, computeSchedule, packSchedule } from './graph.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

async function main() {
  const args = process.argv.slice(2)

  let mode
  let workers

  if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) {
    mode = args[0]
  } else if (args.length === 2 && args[0] === 'pack') {
    mode = 'pack'
    const workersStr = args[1]
    if (!/^[1-9][0-9]*$/.test(workersStr)) {
      process.stderr.write('error: workers must be a positive integer\n')
      process.exit(2)
    }
    workers = parseInt(workersStr, 10)
  } else {
    process.stderr.write(USAGE + '\n')
    process.exit(2)
  }

