    let total = 0
    for (const { depth, finish } of schedule.values()) {
      if (depth > maxDepth) maxDepth = depth
      if (finish > total) total = finish
    }
    const lines = []
    for (let d = 0; d <= maxDepth; d++) {
      const names = []
      for (const [name, info] of schedule.entries()) {
        if (info.depth === d) names.push(name)
      }
      names.sort()
      lines.push(`wave ${d}: ${names.join(' ')}`)
    }
    lines.push(`total ${total}`)
    process.stdout.write(lines.join('\n') + '\n')
  } else if (mode === 'explain') {
    const schedule = computeSchedule(tasks, deps)
    let total = 0
    for (const { finish } of schedule.values()) {
      if (finish > total) total = finish
    }
    const names = [...tasks.keys()].sort()
    const lines = []
    for (const name of names) {
      const { start, finish, depth } = schedule.get(name)
      lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
    }
    lines.push(`total ${total}`)
    process.stdout.write(lines.join('\n') + '\n')
  } else if (mode === 'pack') {
    const { runs, makespan } = packSchedule(tasks, deps, workers)
    const lines = []
    for (let w = 0; w < workers; w++) {
      const parts = runs[w].map((r) => ` ${r.name}@${r.start}-${r.finish}`)
      lines.push(`worker ${w}:${parts.join('')}`)
    }
    lines.push(`makespan ${makespan}`)
    process.stdout.write(lines.join('\n') + '\n')
  }
